import base64
from pathlib import Path

_root = Path("/marimo/storage/cube666_stabilizer_v1")
_files = {
    "scripts/60_train_stabilizer_stage.py": "",
    "stabilizer_ladder_v1.json": "",
}
for _relative, _payload in _files.items():
    _target = _root / _relative
    _target.parent.mkdir(parents=True, exist_ok=True)
    _target.write_bytes(base64.b64decode(_payload))
print({str(_root / _relative): (_root / _relative).stat().st_size for _relative in _files})

